</style></head><body><section class="brand-side"><div class="brand"><img class="login-logo" src="{{ route('company.logo') }}" alt="{{ $companySettings['company_name']??'Pump Manager' }} logo"></div><div class="hero"><div class="eyebrow">Fuel operations, in control</div><h1>Every shift.<br>Every station.<br>One clear view.</h1><p>Track daily sales, nozzle readings and team performance with confidence. Your station operations, all in one place.</p><div class="hero-rule"></div><div class="hero-metrics"><div><strong>Live</strong><span>station overview</span></div><div><strong>Secure</strong><span>role-based access</span></div></div></div><div class="brand-foot">© {{ now()->year }} {{ $companySettings["company_name"]??"Pump Manager" }} · Operations workspace</div></section><main class="form-side"><div class="login-card"><div class="mobile-brand"><img class="login-logo" src="{{ route('company.logo') }}" alt="{{ $companySettings['company_name']??'Pump Manager' }} logo"></div><h1 class="welcome">Welcome back</h1><p class="sub">Sign in to continue to your station dashboard.</p><form method="post" action="{{ route('login.store') }}">@csrf<div class="mb-3"><label class="form-label" for="identity">Email or mobile number</label><input id="identity" class="form-control" name="identity" value="{{ old('identity') }}" placeholder="Enter your email or mobile" autocomplete="username" required autofocus></div><div class="mb-3"><label class="form-label" for="password">Password</label><div class="input-wrap"><input id="password" class="form-control" name="password" type="password" placeholder="Enter your password" autocomplete="current-password" required><button type="button" class="toggle-pass" onclick="const p=document.getElementById('password');p.type=p.type==='password'?'text':'password';this.textContent=p.type==='password'?'Show':'Hide'">Show</button></div></div><div class="d-flex justify-content-between align-items-center mb-4"><label class="remember"><input type="checkbox" name="remember" class="form-check-input me-1"> Remember me</label><span class="remember">Contact your administrator for access</span></div><button class="sign-in w-100">Sign in to workspace <span class="ms-1">→</span></button></form><div class="form-note">Protected access · {{ $companySettings["company_name"]??"Pump Manager" }}</div></div></main>@if(session('errors') && session('errors')->any())<span id="login-error" data-message="{{ session('errors')->first() }}" hidden></span>@endif<script src="https://cdn.jsdelivr.net/npm/toastify-js"></script><script>const err=document.getElementById('login-error');if(err&&window.Toastify)Toastify({text:err.dataset.message,duration:4500,gravity:'top',position:'right',close:true,style:{background:'#a33b35'}}).showToast()</script></body></html>
